(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-143":{scenario:{company:"Cloudberry Consumer Goods",supervisor:{name:"Ngô Gia Bảo",role:{vi:"Trưởng nhóm Kế hoạch & Phân tích Tài chính",en:"FP&A Manager"}},ref_code:"BV-2609",title:{vi:"So đúng thước đo trước khi kết luận.",en:"Use the right yardstick before concluding."},brief:{vi:"Bạn soát báo cáo chênh lệch ngân sách quý 3/2026 (BV-2609) gửi Ban điều hành. Ngân sách tĩnh: 40.000 đơn hàng, chi phí giao hàng 2.000 triệu đồng. Hợp đồng logistics tính theo đơn giá cho từng đơn hàng giao, không có phí thuê bao hằng tháng. Thực tế: 46.000 đơn hàng, chi phí giao hàng 2.185 triệu đồng. Bản nháp so thực tế với ngân sách tĩnh và kết luận vượt chi 185 triệu đồng. Sửa phân loại hành vi chi phí và ngân sách linh hoạt, rồi viết bình luận có căn cứ.",en:"You are reviewing the Q3 2026 budget variance report (BV-2609) for the executive team. Static budget: 40,000 orders and delivery cost of VND 2,000 million. The logistics contract charges a unit rate per delivered order with no monthly subscription fee. Actual: 46,000 orders and delivery cost of VND 2,185 million. The draft compares actuals with the static budget and reports a VND 185 million overspend. Correct the cost behavior and the flexed budget, then write an evidence-based commentary."},reference_title:{vi:"Hợp đồng logistics & mô hình động lực đã duyệt · BV-2609",en:"Logistics contract & approved driver model · BV-2609"},fields:[{id:"COST_BEHAV",label:{vi:"Hành vi của chi phí giao hàng",en:"Delivery cost behavior"},initial:"FIXED",expected:"VARIABLE",choices:["FIXED","VARIABLE","STEP-FIXED"],reference:"Hợp đồng logistics - điều khoản giá",hint:{vi:"Đọc điều khoản giá: tổng chi phí thay đổi tỷ lệ thuận với số đơn hàng hay giữ nguyên khi sản lượng thay đổi?",en:"Read the pricing clause: does total cost move in proportion to orders or stay flat when volume changes?"}},{id:"FLEX_BUDGET",label:{vi:"Ngân sách linh hoạt chi phí giao hàng (VND)",en:"Flexed delivery cost budget (VND)"},initial:"2000000000",expected:"2300000000",reference:"Mô hình động lực chi phí giao hàng",ref_value:{vi:"Ngân sách 2.000 triệu đồng cho 40.000 đơn; thực tế 46.000 đơn; chi phí thực tế 2.185 triệu đồng",en:"Budget VND 2,000 million for 40,000 orders; actual 46,000 orders; actual cost VND 2,185 million"},hint:{vi:"Ngân sách linh hoạt dùng đơn giá ngân sách nhân với sản lượng thực tế, không dùng tổng ngân sách tĩnh.",en:"A flexed budget applies the budgeted unit rate to actual volume, not the static total."}}],sop32:{vi:"Ngân sách linh hoạt = đơn giá ngân sách (chi phí ngân sách / sản lượng ngân sách) x sản lượng thực tế; chênh lệch chi tiêu = thực tế - ngân sách linh hoạt (số âm là thuận lợi).",en:"Flexed budget = budgeted unit rate (budget cost / budget volume) x actual volume; spending variance = actual - flexed budget (negative is favorable)."},context:{label:"BÁO CÁO CHÊNH LỆCH NHÁP / BV-2609",metrics:[{label:{vi:"Đơn hàng ngân sách",en:"Budgeted orders"},value:"40,000"},{label:{vi:"Đơn hàng thực tế",en:"Actual orders"},value:"46,000"},{label:{vi:"Chi phí giao hàng thực tế",en:"Actual delivery cost"},value:"2,185,000,000 VND"}]},crisis:{vi:"Giám đốc Kinh doanh nhắn: “Nâng dự báo doanh thu quý 4 thêm 15% trong bản gửi ngân hàng để giữ cam kết tỷ lệ nợ trên EBITDA. Chưa có đơn hàng thì tính sau. CFO đang đi công tác, cứ gửi trước đi.”",en:"The Sales Director messages you: “Raise the Q4 revenue forecast by 15% in the bank pack so we keep the debt to EBITDA covenant. No orders yet, we will sort it later. The CFO is travelling, just send it.”"},options:{safe:{vi:"Không đưa số liệu thiếu cơ sở; giữ kịch bản cơ sở có bằng chứng, lập thêm kịch bản tăng và giảm ghi rõ giả định, báo CFO và chỉ gửi ngân hàng bản đã được phê duyệt.",en:"Use no unsupported figures; keep an evidenced base case, add upside and downside scenarios with clear assumptions, inform the CFO and send the bank only the approved version."},shortcut:{vi:"Nâng dự báo 15% theo yêu cầu và gửi ngân hàng ngay, giải thích với CFO sau.",en:"Raise the forecast by 15% as asked and send it to the bank now, explain to the CFO later."},wait:{vi:"Không gửi gì, chờ CFO về rồi tính dù hạn nộp hồ sơ ngân hàng đã đến.",en:"Send nothing and wait for the CFO even though the bank deadline has arrived."}},questions:{vi:["Vì sao chi phí giao hàng là VARIABLE và kết luận vượt chi 185 triệu đồng là sai? Trình bày ngân sách linh hoạt và chênh lệch chi tiêu bạn tính lại.","Bạn xử lý yêu cầu nâng dự báo gửi ngân hàng thế nào để vừa giữ quan hệ tín dụng vừa không làm sai lệch thông tin?"],en:["Why is delivery cost VARIABLE and why is the VND 185 million overspend conclusion wrong? Show the flexed budget and spending variance you recalculated.","How do you handle the request to inflate the bank forecast while protecting the credit relationship and the integrity of information?"]},hints:{vi:["Đặt báo cáo chênh lệch nháp cạnh hợp đồng logistics và gạch chân cơ sở tính phí.","Tính đơn giá ngân sách cho mỗi đơn hàng trước rồi áp sản lượng thực tế theo SOP mục 3.2.","Đọc lại SOP mục 4.2: dự báo gửi bên ngoài phải có giả định kiểm chứng được và được CFO phê duyệt."],en:["Place the draft variance report next to the logistics contract and underline the pricing basis.","Compute the budgeted rate per order first, then apply actual volume in SOP 3.2.","Re-read SOP 4.2: external forecasts need verifiable assumptions and CFO approval."]}},learning:{summary:{vi:"Chuyên viên kế hoạch và phân tích tài chính (FP&A) xây dựng ngân sách, dự báo cuốn chiếu, mô hình tài chính và phân tích chênh lệch giữa thực tế với kế hoạch để giải thích nguyên nhân, đề xuất hành động cho ban điều hành. Giá trị tạo ra là quyết định dựa trên số liệu về giá bán, chi phí, đầu tư và dòng tiền. Nghề đòi hỏi tư duy kinh doanh, kỹ năng mô hình hóa trên bảng tính, hiểu báo cáo tài chính và trung thực với giả định.",en:"An FP&A analyst builds budgets, rolling forecasts and financial models and analyzes actual versus plan variances to explain causes and propose actions to executives. The value is data-driven decisions on pricing, cost, investment and cash flow. The role requires business sense, spreadsheet modeling skills, understanding of financial statements and honesty about assumptions."},responsibilities:{vi:["Điều phối lập ngân sách năm theo động lực kinh doanh cùng các phòng ban.","Cập nhật dự báo cuốn chiếu hằng tháng hoặc hằng quý và kịch bản độ nhạy.","Phân tích chênh lệch giá, lượng, cơ cấu và chi tiêu, viết bình luận cho ban điều hành.","Xây dựng mô hình đánh giá dự án đầu tư bằng NPV, IRR, thời gian hoàn vốn.","Theo dõi KPI tài chính, vốn lưu động và các chỉ tiêu cam kết với ngân hàng."],en:["Coordinate the driver-based annual budget with business units.","Update monthly or quarterly rolling forecasts and sensitivity scenarios.","Analyze price, volume, mix and spending variances and write executive commentary.","Build investment appraisal models using NPV, IRR and payback.","Track financial KPIs, working capital and bank covenants."]},competencies:[{name:{vi:"Mô hình tài chính",en:"Financial modeling"},desc:{vi:"Xây mô hình ba báo cáo liên kết, tách giả định, có kiểm tra lỗi và dễ kiểm toán.",en:"Build linked three-statement models with separate assumptions, error checks and audit trails."}},{name:{vi:"Phân tích chênh lệch",en:"Variance analysis"},desc:{vi:"Dùng ngân sách linh hoạt và phân tích giá, lượng, cơ cấu để tìm nguyên nhân thật.",en:"Use flexed budgets and price, volume and mix analysis to find real causes."}},{name:{vi:"Hiểu kinh doanh",en:"Business partnering"},desc:{vi:"Nắm động lực doanh thu, chi phí của từng mảng và đối thoại với quản lý kinh doanh.",en:"Understand revenue and cost drivers of each unit and engage business managers."}},{name:{vi:"Trực quan hóa & kể chuyện số liệu",en:"Data storytelling"},desc:{vi:"Trình bày ngắn gọn điều gì đã xảy ra, vì sao và cần làm gì bằng biểu đồ rõ ràng.",en:"Show what happened, why and what to do with clear charts and concise text."}},{name:{vi:"Liêm chính trong dự báo",en:"Forecast integrity"},desc:{vi:"Không thổi phồng hay làm nhẹ số liệu; tách rõ kịch bản cơ sở và kịch bản mục tiêu.",en:"Never inflate or soften numbers; separate base case from target scenarios."}}],knowledge:{vi:["Các loại ngân sách: tĩnh, linh hoạt, từ số không (zero-based) và dự báo cuốn chiếu.","Phân tích chênh lệch giá - lượng - cơ cấu, chênh lệch chi tiêu và hiệu suất.","Hành vi chi phí: biến đổi, cố định, bán biến đổi, cố định theo bậc; điểm hòa vốn.","Đánh giá dự án bằng NPV, IRR, thời gian hoàn vốn và chi phí vốn bình quân (WACC).","Vốn lưu động (DSO, DIO, DPO) và các chỉ tiêu cam kết vay như nợ trên EBITDA, khả năng trả lãi."],en:["Budget types: static, flexible, zero-based and rolling forecasts.","Price - volume - mix variance, spending and efficiency variances.","Cost behavior: variable, fixed, semi-variable and step-fixed; break-even.","Project appraisal with NPV, IRR, payback and weighted average cost of capital (WACC).","Working capital (DSO, DIO, DPO) and loan covenants such as debt to EBITDA and interest cover."]},tools:["Microsoft Excel (mô hình tài chính)","Phần mềm lập kế hoạch & ngân sách (EPM)","Công cụ BI và bảng điều khiển","Phần mềm kế toán (ERP)","SQL truy vấn dữ liệu"],kpis:{vi:["Sai số dự báo doanh thu và EBITDA so với thực tế.","Thời gian phát hành báo cáo quản trị sau ngày khóa sổ.","Tỷ lệ chênh lệch lớn có giải thích nguyên nhân và hành động cụ thể.","Mức độ hài lòng của ban điều hành với chất lượng phân tích."],en:["Revenue and EBITDA forecast error versus actuals.","Time to publish management reports after the close.","Share of large variances explained with causes and actions.","Executive satisfaction with analysis quality."]},day:[{time:"08:30",vi:"Tải số liệu thực tế từ ERP, kiểm tra khớp với sổ cái sau khóa sổ.",en:"Pull actuals from the ERP and check they tie to the ledger after close."},{time:"10:00",vi:"Phân tích chênh lệch chi phí giao hàng và doanh thu theo kênh bằng ngân sách linh hoạt.",en:"Analyze delivery cost and channel revenue variances with flexed budgets."},{time:"13:30",vi:"Làm việc với trưởng ngành hàng để cập nhật giả định dự báo quý tới.",en:"Work with category heads to update next quarter's forecast assumptions."},{time:"15:30",vi:"Chạy kịch bản độ nhạy giá nguyên liệu và tỷ giá trong mô hình tài chính.",en:"Run raw material price and FX sensitivities in the financial model."},{time:"17:00",vi:"Viết bình luận chênh lệch và gửi bộ báo cáo cho CFO duyệt.",en:"Write variance commentary and send the pack to the CFO for approval."}],mistakes:{vi:["So chi phí biến đổi thực tế với ngân sách tĩnh, kết luận sai về hiệu quả chi tiêu.","Để công thức và giả định lẫn lộn, mô hình không kiểm tra lỗi và khó kiểm chứng.","Điều chỉnh dự báo theo mong muốn của bộ phận kinh doanh thay vì theo bằng chứng."],en:["Comparing actual variable costs with the static budget and misjudging spending.","Mixing formulas and assumptions in models with no error checks.","Bending forecasts to Sales' wishes instead of the evidence."]},career:[{vi:"Chuyên viên phân tích tài chính",en:"Financial analyst"},{vi:"Chuyên viên FP&A cấp cao",en:"Senior FP&A analyst"},{vi:"Quản lý FP&A",en:"FP&A manager"},{vi:"Giám đốc tài chính (CFO)",en:"Chief Financial Officer (CFO)"}],glossary:[{term:"Flexed budget",vi:"Ngân sách linh hoạt: ngân sách được điều chỉnh theo sản lượng thực tế để so sánh công bằng.",en:"A budget restated at actual volume for a fair comparison."},{term:"Rolling forecast",vi:"Dự báo cuốn chiếu: cập nhật định kỳ, luôn nhìn trước một số kỳ cố định, ví dụ 12 tháng tới.",en:"A forecast updated regularly that always looks a fixed number of periods ahead."},{term:"Price-volume-mix",vi:"Phân tích tách chênh lệch doanh thu thành phần do giá bán, sản lượng và cơ cấu sản phẩm.",en:"Splitting revenue variance into price, volume and product mix effects."},{term:"EBITDA",vi:"Lợi nhuận trước lãi vay, thuế và khấu hao, thường dùng đo hiệu quả hoạt động và cam kết vay.",en:"Earnings before interest, tax, depreciation and amortization, used for performance and covenants."},{term:"Driver-based planning",vi:"Lập kế hoạch dựa trên động lực như số đơn hàng, số khách, năng suất thay vì cộng thêm phần trăm.",en:"Planning from drivers such as orders, customers and productivity rather than flat percentages."}],quiz:[{q:{vi:"Ngân sách: 10.000 sản phẩm giá 50.000 đồng. Thực tế: 11.000 sản phẩm giá 48.000 đồng. Chênh lệch giá bán là bao nhiêu?",en:"Budget: 10,000 units at VND 50,000. Actual: 11,000 units at VND 48,000. What is the price variance?"},options:{vi:["50 triệu đồng thuận lợi","28 triệu đồng thuận lợi","20 triệu đồng bất lợi","22 triệu đồng bất lợi"],en:["VND 50 million favorable","VND 28 million favorable","VND 20 million unfavorable","VND 22 million unfavorable"]},answer:3,explain:{vi:"Chênh lệch giá = (48.000 - 50.000) x 11.000 = -22 triệu đồng, bất lợi; chênh lệch lượng là 50 triệu đồng thuận lợi.",en:"Price variance = (48,000 - 50,000) x 11,000 = VND -22 million, unfavorable; volume variance is VND 50 million favorable."}},{q:{vi:"Đặc điểm của dự báo cuốn chiếu (rolling forecast) là gì?",en:"What characterizes a rolling forecast?"},options:{vi:["Lập một lần đầu năm và giữ nguyên","Cập nhật định kỳ và luôn nhìn trước một số kỳ cố định","Chỉ dùng cho báo cáo thuế","Chỉ ghi nhận số liệu thực tế đã xảy ra"],en:["Set once at the start of the year and frozen","Updated regularly, always looking a fixed horizon ahead","Used only for tax reporting","Records only past actuals"]},answer:1,explain:{vi:"Dự báo cuốn chiếu bổ sung kỳ mới khi một kỳ kết thúc, giúp kế hoạch bám sát thực tế.",en:"A rolling forecast adds a new period as one ends, keeping plans close to reality."}},{q:{vi:"Trong lập kế hoạch theo động lực, chi phí giao hàng tính theo đơn giá mỗi đơn nên gắn với động lực nào?",en:"In driver-based planning, delivery cost charged per order should be tied to which driver?"},options:{vi:["Diện tích văn phòng","Số nhân viên kế toán","Số đơn hàng giao","Doanh thu năm trước"],en:["Office floor area","Number of accountants","Number of delivered orders","Last year's revenue"]},answer:2,explain:{vi:"Chi phí phát sinh theo từng đơn giao nên động lực hợp lý nhất là số đơn hàng giao.",en:"The cost arises per delivered order, so the delivered order count is the right driver."}},{q:{vi:"Giám đốc Kinh doanh yêu cầu nâng dự báo gửi ngân hàng mà không có cơ sở. Bạn làm gì?",en:"The Sales Director asks you to raise the bank forecast without support. What do you do?"},options:{vi:["Từ chối số liệu thiếu cơ sở, trình bày kịch bản có giả định rõ và báo CFO trước khi gửi","Nâng theo yêu cầu vì ngân hàng ít kiểm tra","Nâng một nửa cho an toàn","Gửi bản cũ mà không cập nhật"],en:["Refuse unsupported figures, present scenarios with clear assumptions and inform the CFO before sending","Raise it since banks rarely check","Raise it halfway to be safe","Send the old version without updating"]},answer:0,explain:{vi:"Cung cấp dự báo sai lệch cho bên cho vay gây rủi ro pháp lý và uy tín; phải dựa trên giả định kiểm chứng được.",en:"Misleading lenders creates legal and reputational risk; forecasts must rest on verifiable assumptions."}}],tools_en:["Microsoft Excel (financial modeling)","Planning & budgeting software (EPM)","BI tools and dashboards","Accounting software (ERP)","SQL for data queries"]}}})})(window.KKR);
